const portrait = 'assets/506046808_10162812010454621_1982399538928065975_n.jpg';
const arrowSvg = '<svg width="11" height="11" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.5 9.5L9.5 2.5M9.5 2.5H4M9.5 2.5V8"/></svg>';
const arrow = `<span class="arrow" aria-hidden="true">${arrowSvg}</span>`;
const arrowRightSvg = '<svg width="12" height="12" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M1.5 7h11M8.5 2.5l4.5 4.5-4.5 4.5"/></svg>';
const arrowRight = `<span class="arrow arrow-right" aria-hidden="true">${arrowRightSvg}</span>`;
const arrowUpSvg = '<svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 10.5v-9M2.5 5L6 1.5 9.5 5"/></svg>';
const arrowDownSvg = '<svg width="11" height="11" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 1.5v9M2.5 7L6 10.5 9.5 7"/></svg>';
const link = (url, text) => `<a class="text-link" href="${url}">${text}${arrow}</a>`;
const milestones = [
 {id:'helping-hands',date:'2015',name:'Helping Hands Nepal',category:'Humanitarian response',body:'The earthquake was the beginning of a much deeper involvement in humanitarian work. Through Helping Hands Nepal, Chirag worked on shelter, health, essential supplies, community assessments and recovery efforts across affected communities. The experience taught him to look beyond immediate relief and understand what people need to rebuild their lives.',lesson:'Relief is only the beginning.'},
 {id:'robin-hood-army',date:'2016–present',name:'Robin Hood Army Nepal',category:'Volunteer leadership',body:'Volunteer-led action became a continuing part of Chirag’s work. Food distribution, education, healthcare, disaster response and community initiatives became opportunities to bring ordinary citizens into meaningful action.',lesson:'Many people want to contribute; they need a way to come together.'},
 {id:'covid',date:'2020–2021',name:'COVID Response',category:'Community & healthcare',body:'The pandemic brought immediate and unpredictable needs: healthcare, medical support, essential supplies and food. The response reinforced the value of trusted relationships and resources that can be mobilised quickly.',lesson:'During a crisis, connections can become as valuable as resources.'},
 {id:'aasha',date:'2021',name:'Project Aasha',category:'Disaster & community response',body:'Project Aasha looked beyond individual relief activities and tried to understand communities more systematically through research, engagement and practical support.',lesson:'Effective social work begins with understanding the actual need.'},
 {id:'nyef',date:'2022–2023',name:'NYEF Kathmandu',category:'Entrepreneurship & youth leadership',body:'As President of the Kathmandu Chapter of the Nepalese Young Entrepreneurs’ Forum, Chirag worked with young entrepreneurs and leaders through networking, learning, collaboration and entrepreneurship development.',lesson:'Change also happens by creating opportunities and enabling people to lead.'},
 {id:'g20',date:'July 2023',name:'G20 Young Entrepreneurs’ Alliance',category:'Representing Nepal',body:'Representing Nepal provided a wider perspective on entrepreneurship, leadership and the role young business leaders can play in society, while connecting Chirag to an international network.',lesson:'Local work benefits from a wider perspective.'},
 {id:'ncpl',date:'Sept 2024–present',name:'NCPL',category:'Civic & political leadership',body:'This chapter reflects an interest in Nepal’s public life and the systems that shape communities. It added another dimension: understanding how civic participation, leadership and institutions influence everyday lives.'},
 {id:'flood-relief',date:'October 2024',name:'Flood Relief',category:'Emergency & community response',body:'Flood relief brought another emergency-response experience: identifying need, finding the right people, moving resources quickly and ensuring support reached affected communities.',lesson:'Coordination and local knowledge matter as much as resources.'},
 {id:'kuhiro',date:'May 2026',name:'Project Kuhiro',category:'Education & opportunity',body:'Project Kuhiro grew from an opportunity gap. In collaboration with the Goyal Foundation and Junior Empowerment Circle, it supports deserving students from rural Nepal pursuing higher education in Kathmandu.',lesson:'Talent should not be limited by where someone is born.'},
 {id:'ekjut',date:'2026',name:'Ekjut Nepal',category:'Collective action',body:'After more than a decade, Chirag saw a pattern: the same volunteers, businesses, professionals, friends and communities kept showing up. There was already a community. What was missing was structure, recognition and continuity. Ekjut emerged to give that community a name, identity, structure and a way to recognise the people who have contributed.',lesson:'Many People. One Purpose.'}
];
const stories = [
 {id:'community-was-already-there',image:'assets/468521004_10162053915844621_3386736790802216519_n.jpg',category:'Ekjut',title:'The community was already there.',excerpt:'Before there was a name, there were people who kept showing up. This is why Ekjut exists.',art:'ekjut',label:'The next chapter',milestone:'ekjut',body:['For years, people had been coming together around different needs. A volunteer offered time. A business provided resources. A doctor offered expertise. Someone connected the team to a community. Someone arranged transport. Another person simply asked how they could help.','Different people. Different organisations. Different projects. But often the same underlying community.','These relationships should not disappear when a project ends. There needs to be a way to recognise contributors, stay connected, understand who can contribute what, and respond faster when a new need emerges.','Ekjut is the institutional expression of that idea: a platform for connecting people, resources and capabilities around real needs. It gives a name and a structure to a community that already exists.'],lesson:'The willingness to help already existed. The structure did not.'},
 {id:'talent-and-geography',image:'assets/123025536_10158779060204621_6686752857166138746_n.jpg',category:'Education',title:'Talent should not depend on geography.',excerpt:'Project Kuhiro and the practical work of opening doors for students from rural Nepal.',art:'landscape',label:'Education & opportunity',milestone:'kuhiro',body:['Project Kuhiro grew from an opportunity gap: deserving students from rural Nepal need practical support to pursue higher education in Kathmandu.','In collaboration with the Goyal Foundation and Junior Empowerment Circle, the initiative connects that ambition with support. Its starting belief is simple: where someone is born should not decide how far they can go.','Education is another expression of the same work that runs through Chirag’s journey—understanding a need, bringing people together and making opportunity more accessible.'],lesson:'Talent should not be limited by where someone is born.'},
 {id:'listening-before-acting',image:'assets/120533379_10158717314544621_8782621098158955233_n.jpg',category:'Communities',title:'First, listen. Then, act.',excerpt:'What Project Aasha taught us about understanding a community before deciding what it needs.',art:'type',artText:'Listen.<br>Understand.<br>Act.',label:'A lesson from the field',milestone:'aasha',body:['A relief activity can address an immediate problem. Understanding a community requires a different kind of attention.','Project Aasha looked beyond individual relief activities. Research, engagement and practical support became part of a more systematic approach to understanding communities.','The lesson was not a complicated one: effective social work begins with understanding the actual need. Listening helps shape what comes next.'],lesson:'Effective social work begins with understanding the actual need.'},
 {id:'relief-is-the-beginning',image:'assets/158135182_10159095173074621_1765273384080391979_n.jpg',category:'Humanitarian response',title:'Relief is only the beginning.',excerpt:'Shelter, recovery and the earthquake that began a deeper commitment to community work.',art:'type',artText:'Show up.<br>Stay with it.',label:'Where it began',milestone:'helping-hands',body:['The earthquake marked the beginning of Chirag’s deeper involvement in humanitarian work through Helping Hands Nepal.','The work included shelter, health, essential supplies, community assessments and recovery efforts across affected communities. Each part of the response revealed needs that extended beyond an immediate delivery.','That experience shaped an enduring perspective: relief matters, but rebuilding lives asks for attention beyond the first response.'],lesson:'Relief is only the beginning.'},
 {id:'people-who-show-up',image:'assets/468421081_10162056323044621_3080602347094246914_n.jpg',category:'Volunteers',title:'Ordinary people. A shared purpose.',excerpt:'Volunteer leadership and the everyday willingness to contribute through Robin Hood Army Nepal.',art:'type',artText:'A little time.<br>A lot of heart.',label:'Volunteer leadership',milestone:'robin-hood-army',body:['Volunteer-led action became a continuing part of Chirag’s work through Robin Hood Army Nepal.','Food distribution, education, healthcare, disaster response and community initiatives created opportunities for ordinary citizens to contribute.','The recurring lesson was that willingness is not the missing ingredient. People need a way to find each other, understand where they can help, and turn that intention into useful action.'],lesson:'Many people want to contribute; they need a way to come together.'},
 {id:'trusted-connections',image:'assets/95019828_10158268398774621_710457645969965056_n.jpg',category:'Health',title:'When everyone needed someone.',excerpt:'Healthcare, essential supplies and the trusted connections behind the pandemic response.',art:'type',artText:'Together,<br>through it.',label:'Community & healthcare',milestone:'covid',body:['The pandemic brought immediate and unpredictable needs: healthcare, medical support, essential supplies and food.','The response reinforced the value of relationships that already existed and resources that could be mobilised quickly.','Being able to reach the right person became part of being able to respond. Trusted connections were a practical resource in their own right.'],lesson:'During a crisis, connections can become as valuable as resources.'},
 {id:'enabling-people-to-lead',image:'assets/515496452_10162916989554621_489928839608275934_n.jpg',category:'Entrepreneurship',title:'Creating room for others to lead.',excerpt:'Learning, networks and opportunity through NYEF Kathmandu and youth entrepreneurship.',art:'type',artText:'Ideas need<br>people.',label:'Entrepreneurship',milestone:'nyef',body:['As President of the Kathmandu Chapter of the Nepalese Young Entrepreneurs’ Forum, Chirag worked with young entrepreneurs and leaders.','Networking, learning, collaboration and entrepreneurship development were ways to support people building their own paths.','The experience widened the meaning of social contribution. Change also happens by creating opportunities and enabling others to lead.'],lesson:'Change also happens by creating opportunities.'}
];
const categories = ['All stories','Ekjut','Education','Communities','Humanitarian response','Volunteers','Health','Entrepreneurship'];
const current = location.pathname.split('/').pop().replace('.html','') || 'index';
const navItems = [['journey','My Journey'],['work','My Work'],['ekjut','Ekjut Nepal'],['stories','Stories'],['impact','Impact']];
const brand = '<a class="brand" href="index.html" aria-label="Chirag Goyal — Home"><strong>CHIRAG GOYAL<span style="color:#819369">.</span></strong><small>People · Purpose · Possibility</small></a>';
const menuIconSvg = '<span class="menu-icon" aria-hidden="true"><svg width="14" height="11" viewBox="0 0 16 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="0" y1="1" x2="16" y2="1"/><line x1="0" y1="6" x2="16" y2="6"/><line x1="0" y1="11" x2="16" y2="11"/></svg></span>';
