const header = `<header class="site-header"><div class="wrap header-inner">${brand}<button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu ${menuIconSvg}</button><nav id="navigation" class="desktop-nav" aria-label="Main navigation">${navItems.map(([id,name])=>`<a href="${id}.html" ${current===id?'aria-current="page"':''}>${name}</a>`).join('')}<a class="nav-cta" href="ekjut.html#join">Join the network ${arrow}</a></nav></div></header>`;
const footer = `<footer><div class="wrap"><div class="footer-top"><div>${brand}<p class="footer-note">Rooted in Nepal. Connected by purpose.</p></div><nav class="footer-links" aria-label="Footer navigation">${navItems.map(([id,name])=>`<a href="${id}.html">${name}</a>`).join('')}<a href="collaborate.html">Collaborate</a></nav></div><div class="footer-bottom"><span>© 2026 Chirag Goyal</span><span>People. Communities. A stronger Nepal.</span><a href="#main" class="back-to-top">Back to top <span class="arrow arrow-up" aria-hidden="true">${arrowUpSvg}</span></a></div></div></footer>`;
const invite = `<section class="invitation"><div class="wrap invite-inner"><div><div class="eyebrow">There’s a place for you here</div><h2>Bring what you can.</h2><p>Time. Skills. Resources. Ideas. Sometimes the most useful thing is simply an introduction.</p></div><a class="button" href="collaborate.html">Let’s make a connection ${arrow}</a></div></section>`;
function art(story, extra=''){if(story.image)return `<div class="story-art photo-art ${extra}"><img src="${story.image}" alt="${story.label}" loading="lazy"><small class="art-label">${story.label}</small></div>`;return `<div class="story-art ${story.art==='ekjut'?'ekjut-art':story.art==='type'?'type-art':''} ${extra}" aria-hidden="true">${story.art==='landscape'?`<img src="${landscape}" alt="" loading="lazy">`:story.art==='ekjut'?'<strong>ekjut.</strong>':`<span>${story.artText}</span>`}<small class="art-label">${story.label}</small></div>`;}
function card(s){return `<article class="story-card"><a href="story.html?id=${s.id}" tabindex="-1" aria-hidden="true">${art(s)}</a><div class="story-meta"><span>${s.category}</span><span>·</span><span>${Math.max(1,Math.ceil(s.body.join(' ').split(' ').length/180))} min read</span></div><h3><a href="story.html?id=${s.id}">${s.title}</a></h3><p>${s.excerpt}</p><a class="read-story" href="story.html?id=${s.id}" aria-label="Read ${s.title}">Read the story ${arrow}</a></article>`;}
function heading(label,title,description=''){return `<section class="page-heading"><div class="wrap"><div class="breadcrumb"><a href="index.html">Home</a><span>/</span><span>${label}</span></div><div class="eyebrow">${label}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div></section>`;}
function ekjutFeature(){return `<section class="ekjut-feature"><div class="wrap"><div class="ekjut-layout"><div><div class="eyebrow">The next chapter · Founded by Chirag Goyal</div><div class="ekjut-word">ekjut.</div><div class="ekjut-tagline">Many People. One Purpose.</div></div><div><h2>The willingness was there.<br>Now, a way to come together.</h2><p>A platform connecting people, resources and ideas with communities and real needs. Built on years of showing up, together.</p>${link('ekjut.html','Discover Ekjut Nepal')}</div></div><div class="ekjut-bottom"><span>People + Resources + Ideas → Collective action</span><a href="ekjut.html#registry">Meet the People Registry ${arrow}</a></div></div></section>`;}
function home(){return `<section class="hero"><img class="hero-image" src="${landscape}" alt="A mountain trail and Buddhist stupa in the Nepal Himalayas" fetchpriority="high"><div class="wrap hero-inner"><div class="eyebrow"><span class="dot"></span>Entrepreneur · Leader · Volunteer</div><h1>Good things happen<br>when people<br><span>come together.</span></h1><p class="hero-copy">Bringing people, resources and ideas together to create meaningful change.</p>${link('journey.html','Explore my journey')}<div class="hero-side">PEOPLE · PURPOSE · POSSIBILITY</div><div class="hero-bottom"><span>27.7172° N &nbsp; 85.3240° E &nbsp; / &nbsp; Based in Kathmandu</span><span>Nepal, in perspective &nbsp; ↓</span></div></div></section><div class="wrap topic-strip"><span class="eyebrow">A common thread</span><a href="stories.html?category=Humanitarian%20response">Humanitarian response</a><a href="stories.html?category=Education">Education & opportunity</a><a href="stories.html?category=Volunteers">Volunteer leadership</a><a href="stories.html?category=Entrepreneurship">Entrepreneurship</a><a href="ekjut.html">Collective action ${arrow}</a></div>
<section class="section"><div class="wrap intro"><div class="intro-copy"><div class="eyebrow">A little about me</div><h2>Different chapters.<br>The same belief.</h2><p>For more than a decade, my work has brought me alongside people responding to crises, opening doors and building stronger communities in Nepal.</p><p>The thread through it all? People want to help. Good things happen when we make it easier for them to find each other.</p>${link('journey.html','Get to know me')}<div class="signature">Chirag Goyal</div></div><div class="portrait-layout"><div class="portrait-frame"><img src="${portrait}" alt="Chirag Goyal, pictured in a magazine interview" loading="lazy" width="420" height="387"><div class="portrait-caption"><span>Chirag Goyal</span><span>Entrepreneur. Leader. Volunteer.</span></div></div><span class="portrait-aside">MANY EXPERIENCES. ONE PURPOSE.</span></div></div></section>
<section class="section stories-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Notes from the journey</div><h2>People. Places. Perspectives.</h2></div>${link('stories.html','All stories')}</div><div class="story-grid">${stories.slice(0,3).map(card).join('')}</div></div></section>${ekjutFeature()}
<section class="section"><div class="wrap journey-preview"><div><div class="eyebrow">Looking back. Moving forward.</div><h2>A journey built around people.</h2><p>From emergency response to education and collective action. Each chapter has shaped the next.</p>${link('journey.html','The full journey')}</div><div>${[milestones[0],milestones[1],milestones[4],milestones[9]].map(m=>`<a class="mini-milestone" href="journey.html#${m.id}"><span class="year">${m.date.split('–')[0]}</span><div><h3>${m.name}</h3><p>${m.category}</p></div>${arrow}</a>`).join('')}</div></div></section>${invite}`;}
function journey(){return `${heading('My Journey','It started with showing up.','Relief became recovery. Recovery became resilience. And along the way, the work grew into opportunity, leadership and collective action.')}<section class="section"><div class="wrap journey-full"><aside class="side-note"><div class="eyebrow">The chapters so far</div><p>A curated chronology of the experiences that shaped the work.</p><p>These organisations and initiatives are part of Chirag’s personal journey. Ekjut is the next chapter.</p></aside><div>${milestones.map((m,i)=>`<details class="timeline-row" id="${m.id}" ${i===0?'open':''}><summary><time>${m.date}</time><div><h3>${m.name}</h3><span class="category">${m.category}</span></div></summary><div class="timeline-copy"><p>${m.body}</p>${m.lesson?`<p class="lesson">${m.lesson}</p>`:''}</div></details>`).join('')}</div></div></section>${invite}`;}
function work(){return `${heading('My Work','Many ways to make a difference.','Humanitarian response, volunteer leadership, entrepreneurship and civic engagement. Different forms of work, connected by a commitment to people.')}<section class="section"><div class="wrap work-list">${milestones.map(m=>`<article class="work-item"><div class="eyebrow">${m.category}</div><h3>${m.name}</h3><p>${m.body}</p>${link(`journey.html#${m.id}`,'Explore this chapter')}</article>`).join('')}</div></section>${ekjutFeature()}${invite}`;}
function ekjut(){const groups=[['Volunteers','The people who bring their time and energy.'],['Resource contributors','The people who make materials, services and support available.'],['Experts','The professionals who share their skills and experience.'],['Community connectors','The people who understand local needs and build trust.'],['Partners','The organisations and institutions that work alongside us.'],['Idea builders','The people who see a possibility and help make it practical.']];const steps=[['Understand','Start with the actual need.'],['Verify','Understand the situation and resources required.'],['Connect','Find the right people, expertise and organisations.'],['Mobilise','Bring the required resources together.'],['Act','Execute practically and responsibly.'],['Account','Document what was contributed, done and changed.'],['Stay connected','Keep relationships and learning alive beyond a single project.']];return `${heading('Ekjut Nepal','Many People.<br>One Purpose.','A social-impact platform founded by Chirag Goyal. Connecting people, resources, skills and institutions with communities and real needs.')}<section class="section"><div class="wrap split-copy"><div><div class="eyebrow">Why Ekjut?</div><h2 style="margin-top:20px">It was already happening.</h2></div><div><p>A volunteer offered time. A business provided resources. A doctor offered expertise. Someone arranged transport. Another person simply asked, “How can I help?”</p><p>Different organisations. Different projects. Often the same underlying community. What was missing was structure, recognition and continuity.</p><p>Ekjut gives that community a name—and a way to come together again.</p></div></div></section><section class="section quote-section"><div class="wrap"><div class="eyebrow">The belief behind it</div><p class="statement">“People who want to help are everywhere. The opportunity is to make it easier for them to find each other.”</p></div></section><section class="section"><div class="wrap"><div class="eyebrow">How Ekjut works</div><h2 style="margin-top:20px">From need to action.</h2><div class="process">${steps.map(([title,body])=>`<div class="process-item"><h3>${title}</h3><p>${body}</p></div>`).join('')}</div></div></section><section class="section stories-section" id="registry"><div class="wrap"><div class="section-head"><div><div class="eyebrow">The Ekjut People Registry</div><h2>You were part of this.</h2></div></div><p class="muted" style="max-width:730px">Ekjut is not beginning with zero people. It is beginning with a history. The voluntary People Registry is intended to recognise the people behind the work and create a trusted network that can come together again.</p><div class="registry-grid">${groups.map(([t,p])=>`<div class="registry-item"><h3>${t}</h3><p>${p}</p></div>`).join('')}</div><p class="notice">The People Registry is being developed. Registration is not open yet. Participation will be voluntary, with clear consent and privacy arrangements before any personal information is collected.</p></div></section>${invite}`;}
function impact(){return `${heading('Impact','The work is about people.','Behind every response is a community, a relationship and a lesson. These are areas of contribution across Chirag’s journey.')}<section class="section"><div class="wrap impact-grid">${[['Shelter & recovery','Helping Hands Nepal','Supporting shelter, essential needs and community recovery after the earthquake.','helping-hands'],['Community & healthcare','COVID Response','Connecting healthcare support and essential supplies during a national emergency.','covid'],['Volunteer-led action','Robin Hood Army Nepal','Creating ways for citizens to contribute to food, education, healthcare and community initiatives.','robin-hood-army'],['Understanding needs','Project Aasha','Bringing research and community engagement into practical support.','aasha'],['Education & opportunity','Project Kuhiro','Supporting deserving rural students pursuing higher education in Kathmandu.','kuhiro'],['Collective action','Ekjut Nepal','Building continuity, recognition and accountability around people’s contributions.','ekjut']].map(([t,o,p,id])=>`<article class="impact-item"><div class="eyebrow">${o}</div><h3>${t}</h3><p>${p}</p><div style="margin-top:20px">${link(`journey.html#${id}`,'Read the context')}</div></article>`).join('')}</div></section><section class="section quote-section"><div class="wrap split-copy"><h2>Numbers matter.<br>Context matters more.</h2><div><p>Outcomes should be connected to the communities, contributors and organisations behind them. Work undertaken through earlier organisations belongs to those chapters of Chirag’s journey.</p><p>Ekjut’s work will be documented as its own chapter, with contributions, actions and outcomes made clear.</p></div></div></section>${invite}`;}
function archive(){return `${heading('Stories','People. Places.<br>Lessons worth sharing.','A living collection of the people, communities and ideas behind the work. One story at a time.')}<section class="section"><div class="wrap"><div class="filter-toolbar"><div class="filters" role="group" aria-label="Filter stories by topic">${categories.map((c,i)=>`<button class="filter-button" data-category="${c}" aria-pressed="${i===0}">${c}</button>`).join('')}</div><div class="search-wrap"><label class="sr-only" for="story-search">Search stories</label><input type="search" id="story-search" placeholder="Find a story…"><span aria-hidden="true">⌕</span></div></div><p class="results-count" role="status" aria-live="polite"></p><div class="story-grid archive-grid" id="story-results"></div></div></section>${invite}`;}
function story(){const s=stories.find(s=>s.id===new URLSearchParams(location.search).get('id'));if(!s){document.title='Story not found — Chirag Goyal';return `${heading('Stories','This story isn’t here.','It may have moved, or the link may be incomplete.')}<section class="section"><div class="wrap">${link('stories.html','Explore all stories')}</div></section>`;}document.title=`${s.title} — Chirag Goyal`;const m=milestones.find(m=>m.id===s.milestone);return `<section class="page-heading"><div class="wrap article-top"><div class="breadcrumb"><a href="stories.html" class="back-link"><span class="arrow-left" aria-hidden="true"><svg width="11" height="11" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9.5 6H2.5M6 2.5L2.5 6 6 9.5"/></svg></span> Back to all stories</a><span>/</span><span>${s.category}</span></div><div class="eyebrow">${s.category}</div><h1>${s.title}</h1><p>${s.excerpt}</p><div class="story-meta"><span>From Chirag’s journey</span><span>·</span><span>Nepal</span><span>·</span><span>${Math.max(1,Math.ceil(s.body.join(' ').split(' ').length/180))} min read</span></div></div></section><section class="section"><div class="wrap article-wrap">${art(s,'article-art')}${s.art==='landscape'?'<p style="font-size:11px;margin-bottom:30px">Nepal landscape · Illustrative photography, not a project photograph.</p>':''}${s.body.map(p=>`<p>${p}</p>`).join('')}<p class="lesson">${s.lesson}</p><h2>Part of a longer journey.</h2><p>${m.name} is ${m.id==='ekjut'?'the current collective-action platform':'part of Chirag’s personal journey and experience'}.</p><div style="margin-top:25px">${link(`journey.html#${m.id}`,'Explore the chapter')}</div></div></section><section class="section stories-section"><div class="wrap"><div class="section-head"><h2>Keep exploring.</h2>${link('stories.html','All stories')}</div><div class="story-grid">${stories.filter(x=>x.id!==s.id).slice(0,3).map(card).join('')}</div></div></section>`;}
function collaborate(){return `${heading('Collaborate','Good work starts<br>with a conversation.','A skill, an idea, a resource, a connection. There are many ways to be part of something useful.')}<section class="section"><div class="wrap collab-layout"><div><div class="eyebrow">Find your way in</div><h2 style="margin-top:20px">What can you bring?</h2><div class="collab-options">${[['Your time','Help with practical work and community activities. Share your interests, availability and where you are based.'],['Your expertise','Bring professional skills, experience or advice to a need you understand.'],['Resources or a partnership','Connect a business, institution, material resource or service with an opportunity to help.'],['An idea or introduction','Share a community need, a useful connection or an idea you would like to explore.']].map(([t,p],i)=>`<details ${i===0?'open':''}><summary>${t}</summary><p>${p}</p></details>`).join('')}</div><p class="notice" id="contact">Direct contact details will be added here once confirmed. You can prepare an introduction now and save it to share later.</p></div><form class="brief-form"><h3>Prepare an introduction.</h3><p>Put your thoughts in one place. Download a short introduction to share when you’re ready. Nothing is sent or stored by this site.</p><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" maxlength="100" required placeholder="How should we address you?"></div><div class="field"><label for="interest">I’d like to contribute</label><select id="interest" name="interest"><option>Time & volunteering</option><option>Skills & expertise</option><option>Resources & partnerships</option><option>An idea or introduction</option></select></div><div class="field"><label for="message">A little about your idea</label><textarea id="message" name="message" required maxlength="3000" placeholder="What do you have in mind? How would you like to help?"></textarea></div><button class="button" type="submit">Download my introduction <span class="arrow arrow-down" aria-hidden="true">${arrowDownSvg}</span></button><p class="form-status" role="status" aria-live="polite"></p></form></div></section>`;}
const heroNavItems=[['journey','About & Journey'],['work','My Work'],['ekjut','Ekjut'],['stories','Stories'],['collaborate','Connect']];
function renderHero(){
  return `<section class="hero-live" aria-label="Chirag Goyal hero">
  <img class="hero-live-image" src="assets/hero-bg.png" alt="Chirag Goyal in his office" fetchpriority="high">
  <div class="hero-live-shade" aria-hidden="true"></div>
  <div class="hero-live-nav">
    <a class="hero-live-brand" href="index.html" aria-label="Chirag Goyal — Home">
      <span class="hero-brand-title">CHIRAG GOYAL</span>
      <span class="hero-brand-sub">— PEOPLE · PURPOSE · POSSIBILITY</span>
    </a>
    <nav aria-label="Hero navigation">
      ${heroNavItems.map(([id,n])=>{
        const href=id==='index'?'index.html':id==='about'?'#about':id==='contact'?'collaborate.html#contact':id==='press'?'stories.html':id+'.html';
        return `<a href="${href}" ${id==='index'?'aria-current="page"':''}>${n}</a>`;
      }).join('')}
      <a class="hero-search" href="stories.html" aria-label="Search stories"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg></a>
    </nav>
    <button class="hero-menu" type="button" aria-controls="hero-drawer" aria-expanded="false" aria-label="Toggle navigation">Menu ${menuIconSvg}</button>
  </div>
  <div class="hero-drawer" id="hero-drawer" aria-hidden="true">
    <button class="hero-drawer-close" type="button" aria-label="Close menu">Close ${closeIconSvg}</button>
    <div class="hero-drawer-links">
      ${heroNavItems.map(([id,n])=>{
        const href=id==='index'?'index.html':id==='about'?'#about':id==='contact'?'collaborate.html#contact':id==='press'?'stories.html':id+'.html';
        return `<a href="${href}" ${id==='index'?'aria-current="page"':''}>${n}</a>`;
      }).join('')}
    </div>
  </div>
  <div class="hero-live-copy">
    <p class="hero-kicker">— A MORE COMPASSIONATE,<br>CONNECTED NEPAL IS POSSIBLE.</p>
    <h1>Bringing people,<br>resources and ideas<br>together to create<br>meaningful change.</h1>
    <div class="hero-rule" aria-hidden="true"></div>
    <p class="hero-role">Executive Director<br><span>Goyal Group Nepal</span></p>
    <div class="hero-actions">
      <a class="hero-btn hero-btn-primary" href="journey.html">EXPLORE MY JOURNEY ${arrowRight}</a>
      <a class="hero-btn hero-btn-secondary" href="ekjut.html">DISCOVER EKJUT ${arrowRight}</a>
    </div>
  </div>
  <aside class="hero-live-aside" aria-hidden="true">
    <span>People<br>Communities<br>Opportunities<br>A Stronger Nepal</span>
    <div class="aside-rule"></div>
  </aside>
  <a class="hero-scroll" href="#about" aria-label="Scroll to explore">
    <span class="scroll-line" aria-hidden="true"></span>
    <span>SCROLL TO EXPLORE</span>
    <span class="scroll-chevron" aria-hidden="true"><svg width="11" height="7" viewBox="0 0 12 7" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M1 1l5 4.5L11 1"/></svg></span>
  </a>
</section>`;
}
function homeExact(){return `${renderHero()}<div class="wrap topic-strip" id="about"><span class="eyebrow">A common thread</span><a href="stories.html?category=Humanitarian%20response">Humanitarian response</a><a href="stories.html?category=Education">Education & opportunity</a><a href="stories.html?category=Volunteers">Volunteer leadership</a><a href="stories.html?category=Entrepreneurship">Entrepreneurship</a><a href="ekjut.html">Collective action ${arrow}</a></div><section class="section"><div class="wrap intro"><div class="intro-copy"><div class="eyebrow">A little about me</div><h2>Different chapters.<br>The same belief.</h2><p>For more than a decade, my work has brought me alongside people responding to crises, opening doors and building stronger communities in Nepal.</p><p>The thread through it all? People want to help. Good things happen when we make it easier for them to find each other.</p>${link('journey.html','Get to know me')}<div class="signature">Chirag Goyal</div></div><div class="portrait-layout"><div class="portrait-frame"><img src="${portrait}" alt="Chirag Goyal" loading="lazy" width="420" height="387"><div class="portrait-caption"><span>Chirag Goyal</span><span>Entrepreneur. Leader. Volunteer.</span></div></div><span class="portrait-aside">MANY EXPERIENCES. ONE PURPOSE.</span></div></div></section><section class="section stories-section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Notes from the journey</div><h2>People. Places. Perspectives.</h2></div>${link('stories.html','All stories')}</div><div class="story-grid">${stories.slice(0,3).map(card).join('')}</div></div></section>${ekjutFeature()}<section class="section"><div class="wrap journey-preview"><div><div class="eyebrow">Looking back. Moving forward.</div><h2>A journey built around people.</h2><p>From emergency response to education and collective action. Each chapter has shaped the next.</p>${link('journey.html','The full journey')}</div><div>${[milestones[0],milestones[1],milestones[4],milestones[9]].map(m=>`<a class="mini-milestone" href="journey.html#${m.id}"><span class="year">${m.date.split('–')[0]}</span><div><h3>${m.name}</h3><p>${m.category}</p></div>${arrow}</a>`).join('')}</div></div></section>${invite}`;}
function ekjutHub(){
 const roles=[['Volunteers','Give time and energy when a genuine need matches your availability.'],['Professionals & experts','Doctors, engineers, lawyers, designers, technologists and educators sharing expertise.'],['Resource contributors','People and businesses providing transport, accommodation, supplies, equipment or services.'],['Community connectors','Local people who understand the need, the terrain and the institutions involved.'],['Organisations & partners','Businesses, NGOs and institutions contributing capacity, infrastructure and reach.'],['Idea builders','People bringing solutions, relationships and a different way to approach a problem.']];
 const needs=[['Medical assistance','Doctors, nurses, medicines or medical supplies.'],['Transport & logistics','Vehicles and practical support to move people or materials.'],['Volunteers','Distribution, coordination, documentation and field support.'],['Essential resources','Food, water, clothing, shelter materials and equipment.'],['Professional support','Engineering, technology, legal, communication and design expertise.'],['Local connections','Trusted people who know the community and relevant institutions.']];
 const steps=[['Identify','Understand what is actually needed.'],['Verify','Confirm the need and an appropriate local contact.'],['Connect','Find the people, organisations and resources that can help.'],['Mobilise','Bring the required people and resources together.'],['Act','Support the community or situation on the ground.'],['Account','Document what was contributed and achieved.'],['Learn','Capture what worked and improve the next response.']];
 return `<section class="hub-hero"><div class="wrap hub-hero-inner"><div><div class="eyebrow">Ekjut Nepal · A civic community platform</div><h1>Many People.<br>One Purpose.</h1><p>A community of people, skills and resources ready to come together when Nepal needs them.</p><div class="hub-actions"><a class="button hub-primary" href="#join">Join the network ${arrow}</a><a class="button hub-secondary" href="#request">Request help ${arrow}</a></div></div><div class="hub-manifesto"><p>The willingness to help has never been missing.</p><p>Across earthquakes, floods, the pandemic and community projects, people have always stepped forward—with time, skills, supplies, transport, technology and connections.</p><strong>Ekjut exists to bring these people together.</strong></div></div></section>
 <nav class="hub-subnav" aria-label="Ekjut page sections"><div class="wrap"><a href="#why">Why Ekjut</a><a href="#network">The Network</a><a href="#how">How it works</a><a href="#trust">Transparency</a><a href="#join">Join</a></div></nav>
 <section class="section" id="why"><div class="wrap split-copy"><div><div class="eyebrow">Why Ekjut?</div><h2 style="margin-top:20px">The answers already exist. They are simply scattered.</h2></div><div><p>When a need appears, the same questions follow: Who can help? Who has the resources? Who knows the area? Who can arrange transport? Who has the right expertise?</p><p>Ekjut creates a way to connect those answers—beyond one emergency, one organisation or one person.</p></div></div></section>
 <section class="section hub-pathways"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Choose a path</div><h2>How will you take part?</h2></div></div><div class="hub-card-grid"><a href="#join"><span>01</span><h3>Join the network</h3><p>Give your time, skills, resources or connections.</p><b>Tell us how you can help ${arrow}</b></a><a href="#needs"><span>02</span><h3>Current needs</h3><p>See the kinds of support a verified need may require.</p><b>Explore needs ${arrow}</b></a><a href="impact.html"><span>03</span><h3>Our work together</h3><p>See what people and communities have accomplished together.</p><b>Explore the work ${arrow}</b></a><a href="stories.html?category=Ekjut"><span>04</span><h3>Stories from Ekjut</h3><p>Real stories of people who stepped forward.</p><b>Read stories ${arrow}</b></a></div></div></section>
 <section class="section" id="network"><div class="wrap"><div class="section-head"><div><div class="eyebrow">The Ekjut network</div><h2>A network of people ready to help.</h2></div></div><div class="registry-grid hub-role-grid">${roles.map(([title,body])=>`<article class="registry-item"><h3>${title}</h3><p>${body}</p></article>`).join('')}</div><p class="hub-pullquote">You don’t have to give money to make a difference.</p></div></section>
 <section class="section hub-needs" id="needs"><div class="wrap"><div class="split-copy"><div><div class="eyebrow">Current needs</div><h2 style="margin-top:20px">When there is a need, we bring the right people together.</h2><p class="muted" style="margin-top:20px">Every request should be assessed and, where appropriate, verified before it is shared through the network.</p></div><div class="hub-need-list">${needs.map(([title,body])=>`<div><h3>${title}</h3><p>${body}</p></div>`).join('')}</div></div><a class="button hub-primary" href="#request">I need help ${arrow}</a></div></section>
 <section class="section" id="how"><div class="wrap"><div class="section-head"><div><div class="eyebrow">How Ekjut works</div><h2>From a need to collective action.</h2></div></div><div class="process hub-process">${steps.map(([title,body])=>`<article class="process-item"><h3>${title}</h3><p>${body}</p></article>`).join('')}</div></div></section>
 <section class="section hub-trust" id="trust"><div class="wrap split-copy"><div><div class="eyebrow">Our principle</div><h2 style="margin-top:20px">We are building a community that knows how to come together.</h2></div><div><h3>Trust is the foundation.</h3><p>Where appropriate, Ekjut will document what was needed, who coordinated it, what was contributed, what was delivered, what changed and what was learned.</p><p>We will avoid inflated numbers and unverified claims. If we don’t know, we will say we don’t know.</p><div class="notice">Ekjut is a community network, not a donation platform. You can belong through your time, expertise, resources, organisation, ideas or connections.</div></div></div></section>
 <section class="section hub-intake" id="join"><div class="wrap collab-layout"><div><div class="eyebrow">Become part of Ekjut</div><h2 style="margin-top:20px">Be ready to help when Nepal needs you.</h2><p class="muted">Joining means you are willing to be contacted when a genuine, appropriate need matches what you can contribute. You choose whether to respond.</p><ul class="hub-checklist"><li>Where you are based</li><li>Your skills or resources</li><li>Physical or remote availability</li><li>How quickly you may be able to respond</li></ul><p class="notice">This frontend preview does not send or store personal information. Your completed introduction downloads only to your device.</p></div><form class="brief-form ekjut-intake" data-kind="network"><h3>Join the network</h3><div class="field"><label for="network-name">Your name</label><input id="network-name" name="name" required autocomplete="name"></div><div class="field"><label for="network-place">Where are you based?</label><input id="network-place" name="place" required></div><div class="field"><label for="network-offer">What can you contribute?</label><textarea id="network-offer" name="details" required placeholder="Time, skills, resources, a connection or an idea"></textarea></div><button class="button" type="submit">Prepare my introduction ${arrow}</button><p class="form-status" role="status" aria-live="polite"></p></form></div></section>
 <section class="section hub-request" id="request"><div class="wrap collab-layout"><div><div class="eyebrow">Need help?</div><h2 style="margin-top:20px">Tell us what is happening.</h2><p>We’ll use the details to understand the requirement and identify what kind of people or resources may be appropriate.</p><p class="notice">This preview prepares a local request file. It does not submit the request to Ekjut.</p></div><form class="brief-form ekjut-intake" data-kind="request"><h3>Prepare a help request</h3><div class="field"><label for="request-name">Contact name</label><input id="request-name" name="name" required autocomplete="name"></div><div class="field"><label for="request-place">Location or community</label><input id="request-place" name="place" required></div><div class="field"><label for="request-details">What is needed?</label><textarea id="request-details" name="details" required></textarea></div><button class="button" type="submit">Prepare request ${arrow}</button><p class="form-status" role="status" aria-live="polite"></p></form></div></section>`;
}
function ekjutIntegrated(){
 const workAreas=[
  ['01 · Disaster & immediate assistance','Ekjut','A voluntary network for genuine needs—from disasters and emergencies to case-by-case humanitarian assistance.',['Volunteers and local responders','Medical, logistics and transport support','Resources, equipment and expertise','Community connectors and organisations'],'“If there is a genuine need anywhere, we should have a way to find the people who can help.”'],
  ['02 · Medical & urgent assistance','Project Sanjivani','A Nepal-focused platform inspired by medical crowdfunding models, connecting genuine cases with people, foundations and institutions willing to support them.',['Identify → Verify → Mobilise → Support → Account'],'“A difficult medical situation should not become an impossible financial situation simply because the right people were never connected.”'],
  ['03 · Education','Every Child Deserves a Chance','Education and food should be basic human rights. Support can come from Nepal, India and anywhere in the world when a child genuinely needs it.',['Schooling and scholarships','Learning materials and technology','Nutrition and essential support','Mentorship and long-term assistance'],'“The goal is not to provide assistance. The goal is to solve the problem.”'],
  ['04 · Business, youth & entrepreneurship','Build Your Own Journey','Helping young people begin and grow entrepreneurial journeys through mentorship, seed funding, knowledge, connections and opportunity.',['Mentorship','Funding and seed capital','Investor and business connections','Entrepreneurship learning'],'“An idea sometimes needs access to the right people more than anything else.”'],
  ['05 · Leadership & public service','Preparing the Next Generation','Building on NCPL to give aspiring public leaders a foundation in leadership, governance, ethics, public responsibility and resource management.',['Mentors, coaches, trainers and guest lecturers','Diverse political perspectives','Practical foundations for public leadership'],'“The country needs people who are prepared to lead before they are asked to lead.”']
 ];
 const workIcons=[
  '<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="24" cy="10" r="4"/><circle cx="10" cy="34" r="4"/><circle cx="38" cy="34" r="4"/><path d="M21 14 13 30M27 14l8 16M14 34h20"/></svg>',
  '<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M24 42s-14-8-14-19a8 8 0 0 1 14-5 8 8 0 0 1 14 5c0 11-14 19-14 19Z"/><path d="M24 17v13M17.5 23.5h13"/></svg>',
  '<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 12c7-3 12-1 17 3v25c-5-4-10-6-17-3ZM41 12c-7-3-12-1-17 3v25c5-4 10-6 17-3Z"/><path d="M24 15v25"/></svg>',
  '<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M24 42V26M24 26c-9 0-14-5-14-14 9 0 14 5 14 14ZM24 31c9 0 14-5 14-14-9 0-14 5-14 14Z"/></svg>',
  '<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 42h32M12 42V24l12-9 12 9v18M18 42V30h12v12M8 24h32"/></svg>'
 ];
 const steps=[['Understand','Start with the actual need.'],['Verify','Understand the situation.'],['Connect','Find the right people.'],['Mobilise','Bring resources together.'],['Act','Execute responsibly.'],['Account','Document contribution and change.'],['Stay connected','Keep relationships alive.']];
 const journey=[
  ['2015 · Helping Hands Nepal','From relief to rebuilding','After the earthquake, Chirag worked with Helping Hands on relief and recovery. The team moved from dispatching relief material to rehabilitation, including homes built alongside communities that learned the process and could carry it forward.'],
  ['2016 · Robin Hood Army Nepal','Connecting surplus with need','The Nepal model connected people and organisations with surplus food or materials directly to organisations serving people in need, including the Make a Wish project.'],
  ['COVID response','Finding a way to keep help moving','The response began on the second day of lockdown, focusing on daily-wage workers and adapting quickly to movement restrictions, safety measures and practical requests.'],
  ['2019–2024 · NYEF','Youth and women empowerment','Through the National Youth Entrepreneurship Forum, Chirag worked on youth and women empowerment, entrepreneurship participation, startup awards and seed funding.'],
  ['NCPL','Leadership and public service','NCPL brought mentors, coaches, trainers and guest lecturers from varied political backgrounds together around leadership, governance, ethics and public responsibility.'],
  ['2026 · Ekjut Nepal','Giving the community structure','The same volunteers, businesses, professionals, friends and communities repeatedly showed up. Ekjut gives that collective willingness a name, a network and continuity.']
 ];
 return `<section class="hub-hero integrated-hero"><div class="wrap hub-hero-inner"><div><div class="eyebrow">Ekjut Nepal · A community built on collective action</div><h1>Many People.<br>One Purpose.</h1><p>People want to help. Ekjut brings them together—connecting time, skills, resources, ideas, businesses and communities with real needs.</p><div class="hub-actions"><a class="button hub-primary" href="#join">Join the Ekjut Network ${arrow}</a><a class="button hub-secondary" href="#work">Explore the work ${arrow}</a></div></div><div class="hub-manifesto"><p>When people come together, difficult things become possible.</p><p>From disasters and medical emergencies to education, entrepreneurship and public service, the work begins by finding a need and connecting the people who can respond.</p><strong>Collective action, made practical.</strong></div></div></section>
 <nav class="hub-subnav" aria-label="Ekjut page sections"><div class="wrap"><a href="#work">Our Work</a><a href="#network">The Network</a><a href="#how">How It Works</a><a href="#journey">My Journey</a><a href="#stories">Stories</a><a href="#join">Join</a></div></nav>
 <section class="section integrated-intro"><div class="wrap split-copy"><div><div class="eyebrow">The common thread</div><h2>From responding to needs to building systems that can respond.</h2></div><div><p>Sometimes it meant responding to a disaster. Sometimes it meant helping one person find medical treatment, helping a child continue education, or giving a young person the opportunity to build a business.</p><p>The thread has always been simple: find a need, bring the right people together, and do whatever is possible to address it.</p></div></div></section>
 <section class="section integrated-work" id="work"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Our work</div><h2>Five ways of showing up.</h2></div><p class="section-note">Different forms of work. The same commitment to people.</p></div><div class="integrated-work-grid">${workAreas.map(([label,title,body,points,quote],index)=>`<article class="integrated-work-card ${index===4?'integrated-work-featured':''}"><div class="work-card-top"><i class="work-icon" aria-hidden="true">${workIcons[index]}</i><span>${label}</span></div><h3>${title}</h3><p>${body}</p><ul>${points.map(point=>`<li><i aria-hidden="true"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m3 8 3 3 7-7"/></svg></i>${point}</li>`).join('')}</ul><blockquote>${quote}</blockquote></article>`).join('')}</div></div></section>
 <section class="section integrated-network" id="network"><div class="wrap split-copy"><div><div class="eyebrow">Ekjut in practice</div><h2>A disaster and immediate-assistance network.</h2><p>When a genuine need arises, Ekjut’s role is to understand it, verify what it can, and bring together the right mix of people, resources and local knowledge.</p></div><div class="integrated-network-list"><div><strong>People</strong><span>Volunteers, professionals, community connectors and organisations.</span></div><div><strong>Resources</strong><span>Medical support, transport, equipment, supplies and expertise.</span></div><div><strong>Responsibility</strong><span>Clear coordination, realistic claims and thoughtful follow-through.</span></div></div></div></section>
 <section class="section" id="how"><div class="wrap"><div class="section-head"><div><div class="eyebrow">How Ekjut works</div><h2>From need to collective action.</h2></div></div><div class="process integrated-process">${steps.map(([title,body])=>`<article class="process-item"><h3>${title}</h3><p>${body}</p></article>`).join('')}</div></div></section>
 <section class="section integrated-journey" id="journey"><div class="wrap"><div class="section-head"><div><div class="eyebrow">My journey</div><h2>The work grew one experience at a time.</h2></div><p class="section-note">These organisations are chapters in Chirag’s experience, not retroactive Ekjut projects.</p></div><div class="integrated-timeline">${journey.map(([date,title,body])=>`<article><time>${date}</time><div><h3>${title}</h3><p>${body}</p></div></article>`).join('')}</div></div></section>
 <section class="section integrated-stories" id="stories"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Stories</div><h2>Behind every number is a human story.</h2></div></div><p class="integrated-story-lede">A living archive of the people, decisions, challenges and lessons behind the work.</p><article class="integrated-story featured-story"><div class="integrated-story-image"><img src="assets/1053-homes.jpg" alt="Community members involved in rebuilding homes after the 2015 earthquake" loading="lazy"></div><div class="integrated-story-copy"><div class="eyebrow">Story 01</div><h3>1,053 Homes</h3><p>After the 2015 earthquake, the response with Helping Hands moved from immediate relief to rehabilitation. Volunteers built the first homes, then taught villagers how to build so the knowledge could travel through the community.</p><p>Helping Hands provided materials; the community provided labour, ownership and the ability to teach their neighbours. The homes became places where families could return, rebuild and begin again.</p><blockquote>“Five volunteers can build a few houses. A community that knows how to build can rebuild an entire neighbourhood.”</blockquote></div></article><div class="integrated-story-pair"><article class="integrated-story text-story"><div><div class="eyebrow">Story 02 · Resilience</div><h3>55 Homes in Langtang Valley</h3><p>In 2020, people in Langtang Valley shared what they had lived through after the 2015 earthquake and the destruction that followed. An elderly woman who had lost both her son and husband stood out for her warmth, joy and enthusiasm for life.</p><p>The story is a reflection on resilience and a community rebuilding hope alongside homes.</p><blockquote>“Sometimes we travel to help others and return having learned something ourselves.”</blockquote><p class="story-caution">The “55 Homes” wording follows the supplied account and is presented as a story title, not as an independently verified figure.</p></div></article><article class="integrated-story dark-story"><div><div class="eyebrow">Story 03 · COVID response</div><h3>The Second Day</h3><p>On the second day of lockdown, the response focused on daily-wage workers who might quickly run out of resources. Help had to move safely within restrictions, coordinating with police and adapting to genuine requests as they emerged.</p><blockquote>“When the world was told to stop moving, helping people meant finding a safe way to keep help moving.”</blockquote></div></article></div></div></section>
 <section class="section hub-trust"><div class="wrap split-copy"><div><div class="eyebrow">The principle</div><h2>There are many people willing to help.</h2></div><div><h3>The challenge is connecting willingness with need.</h3><p>Ekjut will document what was needed, who coordinated it, what was contributed, what was delivered, what changed and what was learned—where appropriate.</p><p>We will avoid inflated numbers and unverified claims. If we don’t know, we will say we don’t know.</p></div></div></section>
 <section class="section hub-intake" id="join"><div class="wrap collab-layout"><div><div class="eyebrow">Join the Ekjut network</div><h2>You don’t have to give money to make a difference.</h2><p class="muted">Give your time, skills, resources, connections, ideas—or simply be available when a genuine need arises. You choose whether to respond.</p><ul class="hub-checklist"><li>Share your experience</li><li>Choose how you can contribute</li><li>Join only when it makes sense</li><li>Stay connected to the work</li></ul><p class="notice">This frontend preview does not send or store personal information. Your completed profile downloads only to your device.</p></div><form class="brief-form ekjut-intake ekjut-network-form" data-kind="network"><div class="ekjut-form-heading"><span>Network profile</span><h3>Tell us how you can be part of Ekjut.</h3></div><div class="field"><label for="network-name">Name</label><input id="network-name" name="name" required autocomplete="name"></div><div class="field"><label for="network-birth-year">Year of birth</label><input id="network-birth-year" name="birthYear" type="number" min="1900" max="2026" inputmode="numeric" required></div><div class="field"><label for="network-help">How do you want to help?</label><select id="network-help" name="help" required><option value="">Choose one or more ways</option><option>Time and volunteering</option><option>Professional skills or expertise</option><option>Resources, services or transport</option><option>Community connections</option><option>Ideas, mentoring or opportunities</option></select></div><fieldset class="ekjut-choice"><legend>Have you worked with us before?</legend><div><label><input type="radio" name="workedWithUs" value="Yes" required> Yes</label><label><input type="radio" name="workedWithUs" value="No"> No</label></div></fieldset><div class="field network-history" hidden><label for="network-history">If yes, in which project and year?</label><textarea id="network-history" name="previousProject" placeholder="For example: Helping Hands Nepal, 2015"></textarea></div><button class="button" type="submit">Prepare my profile ${arrow}</button><p class="form-status" role="status" aria-live="polite"></p></form></div></section>
 <section class="section hub-request" id="request"><div class="wrap collab-layout"><div><div class="eyebrow">Need help?</div><h2>Tell us what is happening.</h2><p>We’ll use the details to understand the requirement and identify what kind of people or resources may be appropriate.</p><p class="notice">This preview prepares a local request file. It does not submit the request to Ekjut.</p></div><form class="brief-form ekjut-intake" data-kind="request"><h3>Prepare a help request</h3><div class="field"><label for="request-name">Contact name</label><input id="request-name" name="name" required autocomplete="name"></div><div class="field"><label for="request-place">Location or community</label><input id="request-place" name="place" required></div><div class="field"><label for="request-details">What is needed?</label><textarea id="request-details" name="details" required></textarea></div><button class="button" type="submit">Prepare request ${arrow}</button><p class="form-status" role="status" aria-live="polite"></p></form></div></section>`;
}
const pages={index:homeExact,journey,work,ekjut:ekjutIntegrated,impact,stories:archive,story,collaborate};
const titles={index:'Chirag Goyal — People. Purpose. Possibility.',journey:'My Journey — Chirag Goyal',work:'My Work — Chirag Goyal',ekjut:'Ekjut Nepal — Many People. One Purpose.',impact:'Impact — Chirag Goyal',stories:'Stories — Chirag Goyal',collaborate:'Collaborate — Chirag Goyal'};
document.title=titles[current]||'Stories — Chirag Goyal';
document.getElementById('site').innerHTML=(current==='index'?'':header)+`<main id="main">${(pages[current]||home)()}</main>`+footer;
const menu=document.querySelector('.menu-toggle');const nav=document.querySelector('.desktop-nav');
function closeMenu(){if(nav){nav.classList.remove('is-open');menu?.setAttribute('aria-expanded','false');if(menu)menu.innerHTML=`Menu ${menuIconSvg}`;}}
if(menu&&nav){menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';nav.classList.toggle('is-open',open);menu.setAttribute('aria-expanded',String(open));menu.innerHTML=open?`Close ${closeIconSvg}`:`Menu ${menuIconSvg}`;});}
const heroMenuBtn=document.querySelector('.hero-menu');const heroDrawer=document.getElementById('hero-drawer');const heroDrawerClose=document.querySelector('.hero-drawer-close');
function closeHeroDrawer(){if(heroDrawer){heroDrawer.classList.remove('is-open');heroDrawer.setAttribute('aria-hidden','true');heroMenuBtn?.setAttribute('aria-expanded','false');}}
if(heroMenuBtn&&heroDrawer){
  heroMenuBtn.addEventListener('click',()=>{const open=!heroDrawer.classList.contains('is-open');heroDrawer.classList.toggle('is-open',open);heroDrawer.setAttribute('aria-hidden',String(!open));if(open)heroDrawerClose?.focus();heroMenuBtn.setAttribute('aria-expanded',String(open));});
  heroDrawerClose?.addEventListener('click',closeHeroDrawer);
  heroDrawer.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeHeroDrawer));
}
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){
    if(nav?.classList.contains('is-open')){closeMenu();menu?.focus();}
    if(heroDrawer?.classList.contains('is-open')){closeHeroDrawer();heroMenuBtn?.focus();}
  }
});
document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))closeMenu();});
matchMedia('(min-width:851px)').addEventListener('change',e=>{if(e.matches){closeMenu();closeHeroDrawer();}});
function openMilestone(){const id=location.hash.slice(1);const target=document.getElementById(id);if(target?.matches('details')){target.open=true;requestAnimationFrame(()=>target.scrollIntoView());}}
if(current==='journey'){openMilestone();window.addEventListener('hashchange',openMilestone);}
if(current==='stories'){
 let category=new URLSearchParams(location.search).get('category')||'All stories';if(!categories.includes(category))category='All stories';const search=document.getElementById('story-search');search.value=new URLSearchParams(location.search).get('q')||'';
 function renderStories(){const q=search.value.trim().toLowerCase();const filtered=stories.filter(s=>(category==='All stories'||s.category===category)&&[s.title,s.excerpt,s.category,...s.body].join(' ').toLowerCase().includes(q));document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===category)));document.querySelector('.results-count').textContent=`${filtered.length} ${filtered.length===1?'story':'stories'}${category==='All stories'?'':` · ${category}`}`;document.getElementById('story-results').innerHTML=filtered.length?filtered.map(card).join(''):'<div class="empty-results"><h3>No stories found.</h3><p>Try another topic or a different search.</p><button class="button outline" id="clear-filters">Show all stories</button></div>';document.getElementById('clear-filters')?.addEventListener('click',()=>{category='All stories';search.value='';renderStories();search.focus();});const url=new URL(location.href);if(category==='All stories')url.searchParams.delete('category');else url.searchParams.set('category',category);if(q)url.searchParams.set('q',search.value);else url.searchParams.delete('q');try{history.replaceState(null,'',url);}catch{ /* Local file previews can restrict history changes. */ }}
 document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;renderStories();}));search.addEventListener('input',renderStories);renderStories();
}
document.querySelector('.brief-form:not(.ekjut-intake)')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const name=String(data.get('name')).trim();const message=String(data.get('message')).trim();const status=document.querySelector('.form-status');if(!name||!message){status.textContent='Please add your name and a short introduction.';return;}const content=`AN INTRODUCTION — CHIRAG GOYAL / EKJUT NEPAL\n\nName: ${name}\nI’d like to contribute: ${data.get('interest')}\n\n${message}\n\nPrepared for sharing. This introduction has not been submitted.\n`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='my-ekjut-introduction.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Your introduction is ready to save. Nothing has been sent.';});

document.querySelectorAll('.ekjut-network-form').forEach(form=>{const history=form.querySelector('.network-history');form.querySelectorAll('input[name="workedWithUs"]').forEach(input=>input.addEventListener('change',()=>{const hasWorked=form.querySelector('input[name="workedWithUs"]:checked')?.value==='Yes';history.hidden=!hasWorked;history.querySelector('textarea').required=hasWorked;}));});
document.querySelectorAll('.ekjut-intake').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);const kind=form.dataset.kind;const name=String(data.get('name')||'').trim();const status=form.querySelector('.form-status');let content='';let filename='';if(kind==='network'){const birthYear=String(data.get('birthYear')||'').trim();const help=String(data.get('help')||'').trim();const worked=String(data.get('workedWithUs')||'').trim();const previousProject=String(data.get('previousProject')||'').trim();if(!name||!birthYear||!help||!worked||(worked==='Yes'&&!previousProject)){status.textContent='Please complete the required profile fields.';return;}content=`EKJUT NETWORK PROFILE\n\nName: ${name}\nYear of birth: ${birthYear}\nHow I want to help: ${help}\nWorked with Ekjut before: ${worked}${previousProject?`\nPrevious project and year: ${previousProject}`:''}\n\nPrepared locally. This information has not been submitted or stored by the website.\n`;filename='ekjut-network-profile.txt';}else{const place=String(data.get('place')||'').trim();const details=String(data.get('details')||'').trim();if(!name||!place||!details){status.textContent='Please complete all three fields.';return;}content=`EKJUT HELP REQUEST\n\nName: ${name}\nLocation: ${place}\nWhat is needed: ${details}\n\nPrepared locally. This information has not been submitted or stored by the website.\n`;filename='ekjut-help-request.txt';}const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Your file is ready. Nothing was sent or stored.';}));
